# test_generate_common_grid_reentry.py
#
# Integration test for the convergence re-entry seam. A MATLAB-converted store
# only carries the geometry stamp_grid_geometry can fill; the archetype-frame
# geometry (matrix_transform, centroids, X/Y, box_corners, mask_positions,
# lagrangian_grid, area_ratios) is regenerated by generate_common_grid. Here we
# drive it from a copy of a real atlas stripped back to its converter output
# (atlas builds add GRID/TIME_AVERAGE to the real stores in place), and assert it
# produces the full GRID_PROPERTIES that both routes ultimately converge on.
import os
import shutil
from pathlib import Path

import numpy as np
import pytest
import zarr

from pyanimalprocessing.rescaling.registration import generate_common_grid

ATLAS = (
    Path(os.environ.get("AP_TEST_DATA", ".")) / "data" / "zarr_atlases" / "protein"
    / "201217_svp_s1l.zarr"
)

# The archetype-frame geometry the converter cannot reconstruct — must appear
# after re-entry.
PARITY_EXCEPTION_ARRAYS = ["centroids", "X", "Y", "box_corners", "mask_positions", "lagrangian_grid", "area_ratios"]

# Full GRID_PROPERTIES schema written by generate_common_grid.
GRID_PROPERTIES_ARRAYS = [
    "X", "Y", "area_ratios", "box_corners", "centroids", "grid_numbers",
    "lagrangian_grid", "mask_positions", "reference_landmarks", "target_landmarks",
]
GRID_PROPERTIES_ATTRS = [
    "box_size_microns", "frame_grid_definition", "grid_box_corners", "grid_type",
    "image_shape", "matrix_transform", "overlap", "reference_animal_parameter",
    "registration_name", "scaling",
]


@pytest.fixture(scope="module")
def regenerated_grid(tmp_path_factory):
    if not ATLAS.exists():
        pytest.skip("real atlas store not on disk")
    dst = tmp_path_factory.mktemp("reentry") / "atlas.zarr"
    shutil.copytree(ATLAS, dst)
    animal = zarr.open_group(str(dst), mode="r+")
    # back to the converter output: drop what atlas builds added to the real store
    for group in ("GRID", "TIME_AVERAGE"):
        if group in animal:
            del animal[group]
    for key in ("frame_ref", "time_ref"):
        animal.attrs.pop(key, None)
    generate_common_grid(
        [animal], boxsize=[40, 40], overlap=0.5, registration_name="atlas_sr"
    )
    return animal["GRID/EULERIAN/GRID_PROPERTIES"]


def test_reentry_creates_grid_properties(regenerated_grid):
    assert regenerated_grid.attrs["grid_type"] == "eulerian"


def test_reentry_fills_parity_exception_geometry(regenerated_grid):
    # matrix_transform is stored as an attr; the rest as arrays.
    assert "matrix_transform" in regenerated_grid.attrs
    arrays = set(regenerated_grid.array_keys())
    for field in PARITY_EXCEPTION_ARRAYS:
        assert field in arrays, f"{field} missing after re-entry"


def test_reentry_matrix_transform_is_finite_square(regenerated_grid):
    M = np.asarray(regenerated_grid.attrs["matrix_transform"], dtype=float)
    assert M.ndim == 2 and M.shape[0] == M.shape[1]
    assert np.all(np.isfinite(M))


def test_reentry_box_size_microns_matches_request(regenerated_grid):
    box = np.asarray(regenerated_grid.attrs["box_size_microns"], dtype=float)
    np.testing.assert_allclose(box, [40.0, 40.0], atol=1.0)


def test_reentry_area_ratios_are_fractions(regenerated_grid):
    ar = regenerated_grid["area_ratios"][:].astype(np.float32)
    finite = ar[np.isfinite(ar)]
    assert finite.size > 0
    assert np.all(finite >= 0.0)
    assert np.all(finite <= 1.0 + 1e-4)


def test_reentry_has_full_grid_properties_schema(regenerated_grid):
    """The regenerated GRID_PROPERTIES has every field generate_common_grid writes."""
    missing_arrays = set(GRID_PROPERTIES_ARRAYS) - set(regenerated_grid.array_keys())
    missing_attrs = set(GRID_PROPERTIES_ATTRS) - set(regenerated_grid.attrs.keys())
    assert not missing_arrays, f"arrays missing: {missing_arrays}"
    assert not missing_attrs, f"attrs missing: {missing_attrs}"
